// build.js の図を、Google Slides API の batchUpdate の要求に変換する。
// build.js が呼ぶ pptxgenjs の代わりに、呼び出しを記録する偽物を読み込ませ、
// 記録した図形を要求に変換して、スライドの範囲ごとに JSON のファイルに書き出す。
//
// 実行: node gslides.js <出力ディレクトリ> <最初のスライド>-<最後のスライド> [--rgb] [--master <id>] [--delete <id>]
//   --rgb     テーマの色を参照せず、RGB の値で書く（マスターの配色を変えられないとき）
//   --master  マスターの objectId。指定すると、マスターの配色をこの資料のテーマに変える要求を先頭に入れる
//   --delete  消すスライドの objectId（Drive が作った最初のスライド）
// ノートは別に書き出す: node gslides.js <出力ディレクトリ> notes <ノートの ID の JSON>
const fs = require("fs");
const path = require("path");
const Module = require("module");

const PT = 72; // 1 インチのポイント数
// Google スライドのテキストの内側の余白。API では変えられないので、余白 0 の文字の箱をこの分だけ広げる
const PAD_X = 0.1, PAD_Y = 0.05;
const FONT = "Noto Sans JP";
const BULLET_INDENT = 16; // 箇条書きの本文の字下げ（ポイント）

const SHAPES = {
  ROUNDED_RECTANGLE: "ROUND_RECTANGLE", RECTANGLE: "RECTANGLE", OVAL: "ELLIPSE",
  PENTAGON: "HOME_PLATE", CHEVRON: "CHEVRON", CAN: "CAN", LINE: "LINE",
};
const OVERLAY = new Set(["ELLIPSE", "CAN", "CHEVRON", "HOME_PLATE"]);
const SCHEME = {
  text1: "@DARK1", text2: "@DARK2", background1: "@LIGHT1", background2: "@LIGHT2",
  accent1: "@ACCENT1", accent2: "@ACCENT2", accent3: "@ACCENT3",
  accent4: "@ACCENT4", accent5: "@ACCENT5", accent6: "@ACCENT6",
};
const THEME_KEYS = {
  DARK1: "dk1", LIGHT1: "lt1", DARK2: "dk2", LIGHT2: "lt2",
  ACCENT1: "accent1", ACCENT2: "accent2", ACCENT3: "accent3",
  ACCENT4: "accent4", ACCENT5: "accent5", ACCENT6: "accent6",
  HYPERLINK: "hlink", FOLLOWED_HYPERLINK: "folHlink",
};

class FakeSlide {
  constructor(master) { this.master = master; this.items = []; this.notes = ""; }
  addText(t, o) { this.items.push({ kind: "text", t, o }); }
  addShape(type, o) { this.items.push({ kind: "shape", type, o }); }
  addNotes(t) { this.notes = t; }
}
class FakePptx {
  constructor() { this.slides = []; this.masters = {}; this.SchemeColor = SCHEME; this.shapes = SHAPES; }
  defineSlideMaster(m) { this.masters[m.title] = m; }
  addSection() {}
  addSlide({ masterName }) { const s = new FakeSlide(this.masters[masterName]); this.slides.push(s); return s; }
  async writeFile() {}
}

let captured = null;
const origLoad = Module._load;
Module._load = function (request, parent, isMain) {
  if (request === "pptxgenjs") return function () { const p = new FakePptx(); captured = { pres: p }; return p; };
  if (request.endsWith("apply_theme.js")) return { applyTheme: async (_f, theme) => { captured.theme = theme; } };
  return origLoad.apply(this, arguments);
};

// ---- 引数 ----
const [outDir, range, ...rest] = process.argv.slice(2);
const flag = (n) => rest.includes(n);
const opt = (n) => { const i = rest.indexOf(n); return i >= 0 ? rest[i + 1] : undefined; };
process.env.PPTX_SKILL_DIR = process.env.PPTX_SKILL_DIR || "/nonexistent";
process.argv = [process.argv[0], path.join(__dirname, "build.js"), "unused.pptx"];
require("./build.js");

setImmediate(async () => {
  await new Promise((r) => setTimeout(r, 50));
  const { pres, theme } = captured;
  fs.mkdirSync(outDir, { recursive: true });
  if (range === "notes") return writeNotes(pres, JSON.parse(fs.readFileSync(rest[0], "utf8")));
  const [a, b] = range.split("-").map(Number);
  const reqs = [];
  const master = opt("--master");
  if (master) reqs.push(colorSchemeRequest(master, theme));
  for (let n = a; n <= b; n++) reqs.push(...slideRequests(pres.slides[n - 1], n, theme, flag("--rgb")));
  const del = opt("--delete");
  if (del) reqs.push({ deleteObject: { objectId: del } });
  const file = path.join(outDir, `requests-${a}-${b}.json`);
  fs.writeFileSync(file, JSON.stringify(reqs));
  console.log(file, fs.statSync(file).size, "bytes", reqs.length, "requests");
});

// ---- 変換 ----
const r3 = (v) => Math.round(v * 1000) / 1000;
const pt = (inch) => Math.round(inch * PT * 100) / 100;
function hexRgb(hex) {
  const n = parseInt(hex, 16);
  return { red: r3(((n >> 16) & 255) / 255), green: r3(((n >> 8) & 255) / 255), blue: r3((n & 255) / 255) };
}
function color(c, theme, rgb) {
  if (c.startsWith("@")) {
    const k = c.slice(1);
    return rgb ? { rgbColor: hexRgb(theme.colors[THEME_KEYS[k]]) } : { themeColor: k };
  }
  return { rgbColor: hexRgb(c) };
}
function colorSchemeRequest(masterId, theme) {
  const colors = Object.entries(THEME_KEYS).map(([type, k]) => ({ type, color: hexRgb(theme.colors[k]) }));
  return { updatePageProperties: { objectId: masterId, pageProperties: { colorScheme: { colors } }, fields: "colorScheme.colors" } };
}
function geom(page, x, y, w, h) {
  return {
    pageObjectId: page,
    size: { width: { magnitude: pt(w), unit: "PT" }, height: { magnitude: pt(h), unit: "PT" } },
    transform: { scaleX: 1, scaleY: 1, translateX: pt(x), translateY: pt(y), unit: "PT" },
  };
}
const ALIGN = { left: "START", center: "CENTER", right: "END" };
const VALIGN = { top: "TOP", middle: "MIDDLE", bottom: "BOTTOM" };
const DASH = { dash: "DASH", sysDot: "DOT", sysDash: "DASH" };

function slideRequests(slide, n, theme, rgb) {
  const page = `sl_${String(n).padStart(2, "0")}`;
  // スライド番号は作らない。API ではレイアウトのスライド番号のプレースホルダーをスライドに作れないため、
  // Google スライドのメニューの「挿入 > スライド番号」で付ける
  const reqs = [{ createSlide: { objectId: page, insertionIndex: n - 1, slideLayoutReference: { predefinedLayout: "BLANK" } } }];
  const bg = slide.master.background && slide.master.background.color;
  if (bg && bg !== "FFFFFF") {
    reqs.push({ updatePageProperties: { objectId: page, pageProperties: { pageBackgroundFill: { solidFill: { color: color(bg, theme, rgb) } } }, fields: "pageBackgroundFill.solidFill.color" } });
  }
  let k = 0;
  const id = () => `e${String(n).padStart(2, "0")}_${String(++k).padStart(2, "0")}`;
  const col = (c) => color(c, theme, rgb);

  for (const it of slide.items) {
    let o = it.o;
    if (it.kind === "text" && o.placeholder) {
      const ph = slide.master.objects.find((x) => x.placeholder.options.name === o.placeholder).placeholder.options;
      o = Object.assign({}, ph, { isTextBox: true });
    }
    if (it.kind === "shape" && it.type === SHAPES.LINE) { reqs.push(...lineRequests(id(), page, o, col)); continue; }
    if (it.kind === "text" && OVERLAY.has(o.shape)) {
      // Google スライドは円・円柱・山形の中の文字を、図形の内側の狭い四角に収めるので、
      // 図形と文字を分け、図形の外形に合わせた文字の箱を上に重ねる
      slide.items.splice(slide.items.indexOf(it) + 1, 0,
        { kind: "text", t: it.t, o: Object.assign({}, o, { shape: undefined, overlay: true }) });
      it.kind = "shape"; it.type = o.shape;
    }
    const oid = id();
    const isBox = it.kind === "text" && !o.shape;
    let { x, y, w, h } = o;
    const margin = o.margin === undefined ? (isBox && !o.overlay ? 0 : 6) : o.margin;
    if (isBox && o.overlay) {
      const [mt, mr, mb, ml] = (Array.isArray(margin) ? margin : [margin, margin, margin, margin]).map((m) => m / PT);
      x += ml; y += mt; w -= ml + mr; h -= mt + mb;
    }
    if (isBox && (o.overlay || margin === 0)) { x -= PAD_X; y -= PAD_Y; w += 2 * PAD_X; h += 2 * PAD_Y; }
    let shapeType = isBox ? "TEXT_BOX" : (it.kind === "shape" ? it.type : o.shape);
    // Google スライドでは角の丸みを変えられないので、大きな箱は角の丸い四角にしない
    if (shapeType === "ROUND_RECTANGLE" && Math.min(w, h) > 1.0) shapeType = "RECTANGLE";
    reqs.push({ createShape: { objectId: oid, shapeType, elementProperties: geom(page, x, y, w, h) } });

    const sp = {}, fields = [];
    if (!isBox) {
      const f = o.fill || {};
      sp.shapeBackgroundFill = { solidFill: { color: col(f.color || SCHEME.background1) } };
      if (f.transparency) sp.shapeBackgroundFill.solidFill.alpha = r3(1 - f.transparency / 100);
      fields.push("shapeBackgroundFill");
      if (o.line && o.line.color) {
        sp.outline = { outlineFill: { solidFill: { color: col(o.line.color) } }, weight: { magnitude: o.line.width || 1, unit: "PT" } };
        if (o.line.dashType) sp.outline.dashStyle = DASH[o.line.dashType];
      } else sp.outline = { propertyState: "NOT_RENDERED" };
      fields.push("outline");
    }
    const va = VALIGN[o.valign || (isBox && !o.overlay ? "top" : "middle")];
    // 文字の無い図形には、縦の位置を指定しない（要求を短くするため）
    if (it.kind === "text" && (!isBox || va !== "TOP")) { sp.contentAlignment = va; fields.push("contentAlignment"); }
    if (fields.length) reqs.push({ updateShapeProperties: { objectId: oid, shapeProperties: sp, fields: fields.join(",") } });

    if (it.kind === "text") reqs.push(...textRequests(oid, it.t, o, isBox, col));
  }
  return reqs;
}

function lineRequests(oid, page, o, col) {
  const { x, y, w, h } = o;
  const e = geom(page, x, y, w, h);
  // 右から左・下から上の線は、拡大率を負にして向きを反転する
  if (o.flipH) { e.transform.scaleX = -1; e.transform.translateX = pt(x + w); }
  if (o.flipV) { e.transform.scaleY = -1; e.transform.translateY = pt(y + h); }
  const l = o.line;
  const lp = { lineFill: { solidFill: { color: col(l.color) } }, weight: { magnitude: l.width || 1, unit: "PT" },
    dashStyle: l.dashType ? DASH[l.dashType] : "SOLID",
    endArrow: l.endArrowType ? "FILL_ARROW" : "NONE", startArrow: l.beginArrowType ? "FILL_ARROW" : "NONE" };
  return [
    { createLine: { objectId: oid, category: "STRAIGHT", elementProperties: e } },
    { updateLineProperties: { objectId: oid, lineProperties: lp, fields: "lineFill,weight,dashStyle,endArrow,startArrow" } },
  ];
}

function textRequests(oid, t, o, isBox, col) {
  const runs = typeof t === "string" ? [{ text: t, options: {} }] : t;
  let full = "";
  const spans = [];
  runs.forEach((r) => {
    const ro = Object.assign({}, r.options);
    const start = full.length;
    full += r.text + (ro.breakLine ? "\n" : "");
    // 改行も同じ範囲に含める。含めないと改行の文字が既定の大きさのまま残り、その行が高くなる
    spans.push({ start, end: full.length, o: ro });
  });
  if (!full) return [];
  const reqs = [{ insertText: { objectId: oid, text: full } }];
  const styleOf = (ro) => {
    const s = { fontFamily: FONT, fontSize: { magnitude: ro.fontSize || o.fontSize || 18, unit: "PT" } };
    // 新しい箱の文字は太字ではないので、太字のときだけ指定する（要求を短くするため）
    if (ro.bold !== undefined ? ro.bold : o.bold) s.bold = true;
    s.foregroundColor = { opaqueColor: col(ro.color || o.color || SCHEME.text1) };
    if (ro.hyperlink) s.link = { url: ro.hyperlink.url };
    return s;
  };
  const styles = spans.map((sp) => styleOf(sp.o));
  const same = styles.every((s) => JSON.stringify(s) === JSON.stringify(styles[0]));
  const fieldsOf = (s) => "fontFamily,fontSize" + (s.bold ? ",bold" : "") + ",foregroundColor" + (s.link ? ",link" : "");
  if (same) {
    reqs.push({ updateTextStyle: { objectId: oid, textRange: { type: "ALL" }, style: styles[0], fields: fieldsOf(styles[0]) } });
  } else {
    spans.forEach((sp, i) => {
      if (sp.end === sp.start) return;
      reqs.push({ updateTextStyle: { objectId: oid, textRange: { type: "FIXED_RANGE", startIndex: sp.start, endIndex: sp.end }, style: styles[i], fields: fieldsOf(styles[i]) } });
    });
  }
  const ps = {}, pf = [];
  const al = ALIGN[o.align || (isBox && !o.overlay ? "left" : "center")];
  if (!isBox || al !== "START") { ps.alignment = al; pf.push("alignment"); }
  if (o.paraSpaceAfter) { ps.spaceBelow = { magnitude: o.paraSpaceAfter, unit: "PT" }; pf.push("spaceBelow"); }
  if (pf.length) reqs.push({ updateParagraphStyle: { objectId: oid, textRange: { type: "ALL" }, style: ps, fields: pf.join(",") } });
  if (spans.some((sp) => sp.o.bullet)) {
    reqs.push({ createParagraphBullets: { objectId: oid, textRange: { type: "ALL" }, bulletPreset: "BULLET_DISC_CIRCLE_SQUARE" } });
    // 字下げのデフォルト値は大きく、狭い箱では行が折り返されるので、記号の幅だけにする
    reqs.push({ updateParagraphStyle: { objectId: oid, textRange: { type: "ALL" },
      style: { indentFirstLine: { magnitude: 0, unit: "PT" }, indentStart: { magnitude: BULLET_INDENT, unit: "PT" } },
      fields: "indentFirstLine,indentStart" } });
  }
  return reqs;
}

function writeNotes(pres, ids) {
  // ids: { "sl_01": "<speakerNotesObjectId>", ... }
  const reqs = [];
  pres.slides.forEach((s, i) => {
    const page = `sl_${String(i + 1).padStart(2, "0")}`;
    if (s.notes && ids[page]) reqs.push({ insertText: { objectId: ids[page], text: s.notes } });
  });
  const file = path.join(outDir, "requests-notes.json");
  fs.writeFileSync(file, JSON.stringify(reqs));
  console.log(file, fs.statSync(file).size, "bytes", reqs.length, "requests");
}

// スライドのデータの型。
// 資料ごとのスクリプト deck.ts が部品の関数で作り、PowerPoint の書き出しと Google スライドの指示の作成が読む。
// 2 つの書き出しの処理の両方が扱える要素だけを持つ (計画の KTD1)。
// 位置と大きさはインチ、文字の大きさ・線の幅・内側の余白・段落の後の間隔はポイントで持つ。
// 値はすべて決まった値で持ち、省略やデフォルト値を残さない。書き出しの処理がデフォルト値を知らなくて済むようにするため。

import type { Theme } from "./theme.ts";

/** 図形と文字の色に使う、テーマの色の名前。色の値ではなく、この名前で指定する。 */
export type ThemeColorName =
  | "dk1"
  | "lt1"
  | "dk2"
  | "lt2"
  | "accent1"
  | "accent2"
  | "accent3"
  | "accent4"
  | "accent5"
  | "accent6";

/** 位置と大きさ (インチ)。x と y は左上の角。 */
export interface Rect {
  x: number;
  y: number;
  w: number;
  h: number;
}

/** 塗りつぶし。transparency は透明度 (0〜100。0 が不透明)。 */
export interface Fill {
  color: ThemeColorName;
  transparency: number;
}

/** 図形の枠線。width はポイント。 */
export interface Outline {
  color: ThemeColorName;
  width: number;
  dashed: boolean;
}

/** 文字の一部分と、その書式。link は文字に付けるリンクの URL (無ければ null)。 */
export interface TextRun {
  text: string;
  fontSize: number;
  bold: boolean;
  color: ThemeColorName;
  link: string | null;
}

/**
 * 段落。bullet が true なら箇条書きの項目にする。
 * どの段落も部分を 1 つ以上持つ。文字の無い段落 (空行など) は、文字が空の部分を 1 つ持ち、その部分が段落の文字の大きさ・太字・色を表す。
 */
export interface Paragraph {
  runs: TextRun[];
  bullet: boolean;
}

/** 内側の余白 (ポイント)。 */
export interface Margin {
  top: number;
  right: number;
  bottom: number;
  left: number;
}

/** 図形や文字の箱の中の文字。paraSpaceAfter は段落の後の間隔 (ポイント。0 なら間隔を空けない)。 */
export interface TextBody {
  paragraphs: Paragraph[];
  align: "left" | "center" | "right";
  valign: "top" | "middle" | "bottom";
  margin: Margin;
  paraSpaceAfter: number;
}

/**
 * 図形の形。名前は PowerPoint のファイルの形式 (Office Open XML) の形の名前に合わせた。
 * roundRect は角の丸い四角、rect は四角、ellipse は円、can は円柱、chevron は山形、homePlate は五角形の矢印。
 */
export type ShapeKind = "roundRect" | "rect" | "ellipse" | "can" | "chevron" | "homePlate";

/** 形と、形ごとの値。角の丸い四角だけが角の半径 (インチ) を持つ。 */
export type ShapeGeometry =
  | { shape: "roundRect"; radius: number }
  | { shape: Exclude<ShapeKind, "roundRect"> };

/** 図形。中に文字を持てる (文字が無ければ text は null)。枠線が無ければ outline は null。 */
export type ShapeElement = Rect &
  ShapeGeometry & {
    kind: "shape";
    fill: Fill;
    outline: Outline | null;
    text: TextBody | null;
    name: string | null;
  };

/** 塗りつぶしと枠線の無い、文字の箱。 */
export type TextBoxElement = Rect & {
  kind: "textBox";
  text: TextBody;
  name: string | null;
};

/**
 * 線。位置と大きさは、始点と終点を囲む四角で持つ。
 * 始点が終点より右なら flipH、下なら flipV を true にして、向きを表す。
 * endArrow は終点に、startArrow は始点に、矢じりを付けるか。width はポイント。
 * 名前は Google スライドの API の線のプロパティ (endArrow・startArrow) に合わせた。
 * PowerPoint のファイルの形式では、要素 a:headEnd が始点の、a:tailEnd が終点の矢じりを表すので、
 * PowerPoint の書き出しでは endArrow を a:tailEnd に、startArrow を a:headEnd に対応させる。
 */
export type LineElement = Rect & {
  kind: "line";
  flipH: boolean;
  flipV: boolean;
  color: ThemeColorName;
  width: number;
  dashed: boolean;
  endArrow: boolean;
  startArrow: boolean;
};

/** スライドの要素。 */
export type SlideElement = ShapeElement | TextBoxElement | LineElement;

/**
 * 1 つのキーの図。資料ごとのスクリプトが、部品の関数で要素を足して作る。
 * elements の順序は足した順序で、後の要素ほど前面に重なる。
 */
export interface SlideFigure {
  readonly key: string;
  readonly elements: SlideElement[];
}

/**
 * 1 枚のスライドのデータ。題名・一言・発表者ノート (notes) は構成案から、図 (elements) は資料ごとのスクリプトから取る (計画の R8)。
 */
export interface Slide {
  key: string;
  title: string;
  takeaway: string;
  notes: string;
  elements: SlideElement[];
}

/**
 * スライドの大きさ (インチ)。幅 10・高さ 5.625 (横と縦の比が 16:9)。
 * pptxgenjs のレイアウト LAYOUT_16x9 と、Google スライドの新しい資料のデフォルトの大きさと同じ。
 * 部品の関数 title と takeaway の位置と、資料ごとのスクリプトが置く図の位置は、この大きさを前提にする。
 */
export const SLIDE_SIZE = { w: 10, h: 5.625 } as const;

/**
 * 1 つの資料のデータ。2 つの書き出しの処理は、これだけを読む。slides の順序は構成案のスライドの順序。
 * どのスライドも、大きさは SLIDE_SIZE。
 */
export interface Deck {
  /** 資料の題名。構成案の先頭の # の行から取る。PowerPoint のファイルの文書のプロパティ (タイトル) に書く。 */
  title: string;
  theme: Theme;
  slides: Slide[];
}
// テーマ。資料ごとに、6 つのアクセント色の値と意味の名前・フォントを決める (計画の R11)。
// 図形の色はテーマの色の名前で指定し、色の値はテーマだけが持つ。

/** アクセント色。color は 16 進数 6 桁の RGB の値 (例: "0F8B8D")、meaning はその色に割り当てた意味 (例: "新しい版")。 */
export interface AccentColor {
  color: string;
  meaning: string;
}

/**
 * 資料のテーマ。
 * colors はアクセント色以外の 6 色 (dk1 は文字、lt1 は背景、dk2 は補助の文字、lt2 は補助の背景、hlink はリンク、folHlink は開いたリンク)。
 * accents は 6 つのアクセント色で、どれも省略できない。
 * name はテーマの名前で、PowerPoint のファイルに書き込む。
 */
export interface Theme {
  name: string;
  fonts: {
    heading: string;
    body: string;
  };
  colors: {
    dk1: string;
    lt1: string;
    dk2: string;
    lt2: string;
    hlink: string;
    folHlink: string;
  };
  accents: {
    accent1: AccentColor;
    accent2: AccentColor;
    accent3: AccentColor;
    accent4: AccentColor;
    accent5: AccentColor;
    accent6: AccentColor;
  };
}

/** テーマの 12 色の名前。PowerPoint のファイルの形式の配色の名前と同じ。 */
export type SchemeColorName = keyof Theme["colors"] | keyof Theme["accents"];

/** テーマの 12 色の名前を、配色の順序で並べた配列。 */
export const SCHEME_COLOR_NAMES: readonly SchemeColorName[] = [
  "dk1",
  "lt1",
  "dk2",
  "lt2",
  "accent1",
  "accent2",
  "accent3",
  "accent4",
  "accent5",
  "accent6",
  "hlink",
  "folHlink",
];

/** テーマの 12 色の名前と値の対応を返す。PowerPoint のファイルと Google スライドに配色を書き込むときに使う。 */
export function schemeColorValues(theme: Theme): Record<SchemeColorName, string> {
  const { colors, accents } = theme;
  return {
    ...colors,
    accent1: accents.accent1.color,
    accent2: accents.accent2.color,
    accent3: accents.accent3.color,
    accent4: accents.accent4.color,
    accent5: accents.accent5.color,
    accent6: accents.accent6.color,
  };
}

const RGB_HEX = /^[0-9A-Fa-f]{6}$/;

/**
 * テーマの値の誤りを、すべて集めて返す。誤りが無ければ空の配列を返す。
 * 型では検査できない、色の値の形 (16 進数 6 桁。"#" を付けない) と、空の名前・フォント・意味を検査する。
 */
export function checkTheme(theme: Theme): string[] {
  const errors: string[] = [];
  if (theme.name.trim() === "") errors.push("テーマの name が空");
  if (theme.fonts.heading.trim() === "") errors.push("テーマの fonts.heading が空");
  if (theme.fonts.body.trim() === "") errors.push("テーマの fonts.body が空");
  const values = schemeColorValues(theme);
  for (const name of SCHEME_COLOR_NAMES) {
    const value = values[name];
    if (!RGB_HEX.test(value)) {
      errors.push(`テーマの色 ${name} の値 ${JSON.stringify(value)} が、16 進数 6 桁 (例: "0F8B8D") ではない`);
    }
  }
  for (const [name, accent] of Object.entries(theme.accents)) {
    if (accent.meaning.trim() === "") errors.push(`テーマの色 ${name} の meaning が空`);
  }
  return errors;
}
// 資料ごとのスクリプト deck.ts が、名前 slide-deck で import type する型 (計画の KTD2)。
// deck.ts はプラグインのモジュールを実行時に import しないので、ここからは型だけを書き出す。

import type { Parts } from "./data/parts.ts";
import type { SlideFigure } from "./data/types.ts";
import type { Theme } from "./data/theme.ts";

export type {
  ArrowOptions,
  BadgeOptions,
  BoxOptions,
  BulletsOptions,
  CardOptions,
  MarginInput,
  Parts,
  RunInput,
  TextOptions,
} from "./data/parts.ts";
export type { AccentColor, SchemeColorName, Theme } from "./data/theme.ts";
export type {
  Deck,
  Fill,
  LineElement,
  Margin,
  Outline,
  Paragraph,
  Rect,
  ShapeElement,
  ShapeGeometry,
  ShapeKind,
  Slide,
  SlideElement,
  SlideFigure,
  TextBody,
  TextBoxElement,
  TextRun,
  ThemeColorName,
} from "./data/types.ts";

/** 資料ごとのスクリプトの関数が返す値。資料のテーマと、キーごとの図。 */
export interface DeckScriptResult {
  theme: Theme;
  slides: SlideFigure[];
}

/**
 * 資料ごとのスクリプトが default export する関数の型。
 * 部品の関数の集まりを引数で受け取り、テーマとキーごとの図を返す。
 */
export type DeckScript = (p: Parts) => DeckScriptResult;

// 部品の関数。資料ごとのスクリプト deck.ts が、キーごとの図 (SlideFigure) に要素を足すのに使う。
// 引数とデフォルト値は、元にした資料のスクリプト build.js の関数 box・text・arrow・badge・takeaway・card・bullets から引き継いだ。
// 元の関数は pptxgenjs のスライドに直接描いていたが、ここではスライドのデータの要素を図に足す (計画の KTD1)。
// 元のテーマの色の定数は、テーマの色の名前に置き換えた (TEXT は dk1、MUTED は dk2、WHITE は lt1、PANEL は lt2、NEW は accent1)。

import type {
  Margin,
  Paragraph,
  ShapeElement,
  ShapeKind,
  SlideFigure,
  TextBody,
  TextBoxElement,
  ThemeColorName,
} from "./types.ts";

/**
 * 部品の関数 (text・box) に渡す文字の一部分の入力 (以下「入力の部分」)。省略した書式は、その文字を渡した部品の関数の書式を使う。
 * 部品の関数に文字列を渡したときは、その文字列を 1 つの入力の部分として扱う。
 *
 * 部品の関数は、入力の部分の配列を、次の規則で段落に分ける。
 * 入力の部分の文字を改行 ("\n") で分けたものを「行」、文字が空の行を「空の行」と呼ぶ。
 * 文字が空の入力の部分 (text が "") は、空の行を 1 つ持つ。行が段落に入ると、行の文字と、その行の入力の部分の書式から、
 * 型 TextRun の値を作る。段落がどの TextRun を持つかは、規則 4 で決める。
 * 1. breakLine が true の入力の部分の後で、段落を区切る。
 * 2. 入力の部分の文字の改行ごとに、段落を区切る。ただし、文字の最後が改行で、その入力の部分の breakLine が true でなければ、
 *    最後の改行の後の空の行は、どの段落にも入れない。次の入力の部分の行は、区切られた新しい段落に入る。
 * 3. bullet が true の入力の部分は、いまの段落に行が 1 つでも入っていれば (空の行を含む)、その入力の部分の前で段落を区切る。
 *    その入力の部分の行が入った段落は、箇条書きの項目になる。
 * 4. 空でない行が 1 つでも入った段落は、空でない行の TextRun だけを持つ。
 *    空の行だけが入った段落は「空行の段落」になり、最初に入った空の行の TextRun を 1 つだけ持つ。
 * 5. 1 か 2 の区切りで作られた最後の段落に、行が 1 つも入っていなければ、その段落を除く。
 * 6. 行が 1 つも入っていない段落 (入力の部分の配列が空のとき) は、部品の関数の書式の、文字が空の TextRun を 1 つ持つ。
 * 空行の段落にも TextRun を持たせるのは、段落の文字の大きさ・太字・色を書き出しの処理に渡すためである。
 * 空行を入れたいときは、前の入力の部分と、文字が空の入力の部分の両方に breakLine を付ける
 * (例: [{ text: "a", breakLine: true }, { text: "", breakLine: true }, { text: "b" }])。
 * この分け方は pptxgenjs の段落の分け方と同じではなく、改行や pptxgenjs のオプション align の扱いで結果が違う入力がある。
 * PowerPoint の書き出しは、この規則で分けた段落をそのまま pptxgenjs に渡し、段落の分け方を pptxgenjs に任せない。
 * はみ出しの見積もりと Google スライドの指示の作成も、同じ段落を使う。
 */
export interface RunInput {
  text: string;
  fontSize?: number;
  bold?: boolean;
  color?: ThemeColorName;
  link?: string;
  bullet?: boolean;
  breakLine?: boolean;
}

/**
 * 部品の関数の中で扱う文字。1 つの文字列か、書式の違う部分の配列。
 * 関数 box と text の公開する宣言 (オーバーロード) は、この型ではなく文字列と配列の 2 つの形に分けている (理由は関数 box のコメント)。
 * この型を使うのは、2 つの関数の実装のシグネチャと、関数 toParagraphs だけである。
 */
type TextInput = string | RunInput[];

/** 内側の余白の入力 (ポイント)。1 つの数なら上下左右に同じ値を使い、配列なら [上, 右, 下, 左] の順。 */
export type MarginInput = number | [number, number, number, number];

/** 関数 box のオプション。 */
export interface BoxOptions {
  /** 形。デフォルト値は roundRect (角の丸い四角)。 */
  shape?: ShapeKind;
  /** 塗りつぶしの色。デフォルト値は lt1。 */
  fill?: ThemeColorName;
  /** 塗りつぶしの透明度 (0〜100)。デフォルト値は 0。 */
  tr?: number;
  /** 文字の色。デフォルト値は dk1。 */
  color?: ThemeColorName;
  /** 文字の大きさ (ポイント)。デフォルト値は 14。 */
  fontSize?: number;
  /** 太字にするか。デフォルト値は false。 */
  bold?: boolean;
  /** 横の揃え方。デフォルト値は center。 */
  align?: TextBody["align"];
  /** 縦の揃え方。デフォルト値は middle。 */
  valign?: TextBody["valign"];
  /** 内側の余白 (ポイント)。デフォルト値は 6。 */
  margin?: MarginInput;
  /** 角の丸い四角の角の半径 (インチ)。デフォルト値は 0.08。ほかの形では使わない。 */
  radius?: number;
  /** 枠線の色。指定しなければ枠線を描かない。 */
  line?: ThemeColorName;
  /** 枠線の幅 (ポイント)。デフォルト値は 1。 */
  lineW?: number;
  /** 枠線を破線にするか。デフォルト値は false。 */
  dash?: boolean;
  /** 要素の名前。 */
  name?: string;
}

/** 関数 text のオプション。 */
export interface TextOptions {
  /** 文字の大きさ (ポイント)。デフォルト値は 14。 */
  fontSize?: number;
  /** 文字の色。デフォルト値は dk1。 */
  color?: ThemeColorName;
  /** 太字にするか。デフォルト値は false。 */
  bold?: boolean;
  /** 横の揃え方。デフォルト値は left。 */
  align?: TextBody["align"];
  /** 縦の揃え方。デフォルト値は top。 */
  valign?: TextBody["valign"];
  /** 内側の余白 (ポイント)。デフォルト値は 0。 */
  margin?: MarginInput;
  /** 要素の名前。 */
  name?: string;
  /** 段落の後の間隔 (ポイント)。デフォルト値は 0 (間隔を空けない)。 */
  psa?: number;
}

/** 関数 arrow のオプション。 */
export interface ArrowOptions {
  /** 線の色。デフォルト値は dk2。 */
  color?: ThemeColorName;
  /** 線の幅 (ポイント)。デフォルト値は 1.5。 */
  width?: number;
  /** 破線にするか。デフォルト値は false。 */
  dash?: boolean;
  /** 終点の矢じりを付けないか。デフォルト値は false (終点に矢じりを付ける)。 */
  noHead?: boolean;
  /** 始点にも矢じりを付けるか。デフォルト値は false。 */
  both?: boolean;
}

/** 関数 badge のオプション。 */
export interface BadgeOptions {
  /** 円の色。デフォルト値は accent1。 */
  fill?: ThemeColorName;
  /** 番号の文字の大きさ (ポイント)。デフォルト値は 12。 */
  fontSize?: number;
}

/** 関数 card のオプション。 */
export interface CardOptions {
  /** 塗りつぶしの色。デフォルト値は lt2。 */
  fill?: ThemeColorName;
  /** 塗りつぶしの透明度 (0〜100)。デフォルト値は 0。 */
  tr?: number;
  /** 要素の名前。 */
  name?: string;
}

/**
 * 関数 bullets のオプション。
 * 指定しなかった書式は、箇条書きを受け取る部品の関数 (box・text) の書式を使う。
 */
export interface BulletsOptions {
  /** 文字の大きさ (ポイント)。デフォルト値は、受け取る部品の関数の文字の大きさ。 */
  fontSize?: number;
  /** 文字の色。デフォルト値は、受け取る部品の関数の文字の色。 */
  color?: ThemeColorName;
}

/** 文字の書式のうち、部品の関数が決めるもの。文字の一部分の入力で省略した書式に使う。 */
interface RunDefaults {
  fontSize: number;
  bold: boolean;
  color: ThemeColorName;
}

function toMargin(m: MarginInput): Margin {
  if (typeof m === "number") return { top: m, right: m, bottom: m, left: m };
  const [top, right, bottom, left] = m;
  return { top, right, bottom, left };
}

/**
 * 入力の部分の配列を段落に分ける。分け方は、型 RunInput の説明の規則 1〜6 のとおり。
 */
function toParagraphs(t: TextInput, d: RunDefaults): Paragraph[] {
  const inputs: RunInput[] = typeof t === "string" ? [{ text: t }] : t;
  let current: Paragraph = { runs: [], bullet: false };
  const paragraphs: Paragraph[] = [current];
  // fromBreakOnly は、最後の段落が区切りで作られ、まだ行が入っていないか (規則 5 で使う)。
  // 関数 breakParagraph の中でも書き換えるので、変数ではなくオブジェクトのプロパティに持つ
  // (変数にすると、TypeScript の型の検査がクロージャの中の書き換えを考慮せず、常に false と見なす)
  const state = { fromBreakOnly: false };
  const breakParagraph = (): void => {
    current = { runs: [], bullet: false };
    paragraphs.push(current);
    state.fromBreakOnly = true;
  };
  for (const input of inputs) {
    // 規則 3。見出しなど bullet の無い入力の部分の後に、関数 bullets の項目を breakLine なしで続けたときに、
    // 見出しまで箇条書きの段落にしないため (pptxgenjs も、オプション align を指定しなければ、bullet の部分の前で段落を区切る)
    if (input.bullet === true && current.runs.length > 0) breakParagraph();
    const lines = input.text.split("\n");
    lines.forEach((line, i) => {
      // 規則 2
      if (i > 0) breakParagraph();
      // 文字の最後の改行は、breakLine と同じく「この後で段落を区切る」ことだけを表すので、改行の後の空の行は段落に入れない
      // ("a\n" の次の入力の部分が "b" なら、段落は a と b の 2 つで、間に空行の段落を作らない)。
      // ただし入力の部分が breakLine も持つときは、改行と breakLine で 2 回区切るので、間の空行の段落は区切りの後も残る。
      // その段落が入力の部分の書式と bullet を持つように、空の行を入れる
      if (i > 0 && i === lines.length - 1 && line === "" && input.breakLine !== true) return;
      state.fromBreakOnly = false;
      if (input.bullet === true) current.bullet = true;
      const run = {
        text: line,
        fontSize: input.fontSize ?? d.fontSize,
        bold: input.bold ?? d.bold,
        color: input.color ?? d.color,
        link: input.link ?? null,
      };
      if (line === "") {
        // 規則 4。空の行の TextRun は、段落にまだ TextRun が無いときだけ足す (最初の空の行だけを持つため)
        if (current.runs.length === 0) current.runs.push(run);
        return;
      }
      // 規則 4。空でない行の TextRun を足すときは、空の行の TextRun を除く
      current.runs = current.runs.filter((r) => r.text !== "");
      current.runs.push(run);
    });
    // 規則 1
    if (input.breakLine === true) breakParagraph();
  }
  // 規則 5
  if (paragraphs.length > 1 && state.fromBreakOnly) paragraphs.pop();
  // 規則 6
  for (const p of paragraphs) {
    if (p.runs.length === 0) {
      p.runs.push({ text: "", fontSize: d.fontSize, bold: d.bold, color: d.color, link: null });
    }
  }
  return paragraphs;
}

/** 段落に、空でない文字の部分が無いか。 */
function isBlank(p: Paragraph): boolean {
  return p.runs.every((r) => r.text === "");
}

function hasText(paragraphs: Paragraph[]): boolean {
  return paragraphs.some((p) => !isBlank(p));
}

/** 資料ごとのスクリプトが、キーごとの空の図を作る。部品の関数は、この図に要素を足す。 */
export function slide(key: string): SlideFigure {
  return { key, elements: [] };
}

/**
 * 文字の入った箱を足す。形のデフォルト値は角の丸い四角。
 * 文字が空 ("" か空の配列) なら、文字を持たない図形になる (塗りつぶしだけの四角などに使う)。
 */
export function box(
  s: SlideFigure,
  x: number,
  y: number,
  w: number,
  h: number,
  t: string,
  o?: BoxOptions,
): void;
// 文字列と配列を 1 つの引数の型 (string | RunInput[]) にまとめると、配列に書いた bold や link を、
// 規則 no-deprecated が String.prototype の非推奨のメソッドとして誤って指摘する。
// 資料ごとのスクリプトも同じ規則で検査するので、オーバーロードに分けたまま、規則 unified-signatures の指摘の対象から除く
export function box(
  s: SlideFigure,
  x: number,
  y: number,
  w: number,
  h: number,
  // eslint-disable-next-line @typescript-eslint/unified-signatures
  t: RunInput[],
  o?: BoxOptions,
): void;
export function box(
  s: SlideFigure,
  x: number,
  y: number,
  w: number,
  h: number,
  t: TextInput,
  o: BoxOptions = {},
): void {
  const paragraphs = toParagraphs(t, {
    fontSize: o.fontSize ?? 14,
    bold: o.bold ?? false,
    color: o.color ?? "dk1",
  });
  const text: TextBody | null = hasText(paragraphs)
    ? {
        paragraphs,
        align: o.align ?? "center",
        valign: o.valign ?? "middle",
        margin: toMargin(o.margin ?? 6),
        paraSpaceAfter: 0,
      }
    : null;
  const shape = o.shape ?? "roundRect";
  const common = {
    kind: "shape" as const,
    x,
    y,
    w,
    h,
    fill: { color: o.fill ?? "lt1", transparency: o.tr ?? 0 },
    outline:
      o.line === undefined ? null : { color: o.line, width: o.lineW ?? 1, dashed: o.dash ?? false },
    text,
    name: o.name ?? null,
  };
  const element: ShapeElement =
    shape === "roundRect" ? { ...common, shape, radius: o.radius ?? 0.08 } : { ...common, shape };
  s.elements.push(element);
}

/** 塗りつぶしと枠線の無い、文字の箱を足す。 */
export function text(
  s: SlideFigure,
  t: string,
  x: number,
  y: number,
  w: number,
  h: number,
  o?: TextOptions,
): void;
// オーバーロードに分ける理由は、関数 box と同じ
export function text(
  s: SlideFigure,
  // eslint-disable-next-line @typescript-eslint/unified-signatures
  t: RunInput[],
  x: number,
  y: number,
  w: number,
  h: number,
  o?: TextOptions,
): void;
export function text(
  s: SlideFigure,
  t: TextInput,
  x: number,
  y: number,
  w: number,
  h: number,
  o: TextOptions = {},
): void {
  const element: TextBoxElement = {
    kind: "textBox",
    x,
    y,
    w,
    h,
    text: {
      paragraphs: toParagraphs(t, {
        fontSize: o.fontSize ?? 14,
        bold: o.bold ?? false,
        color: o.color ?? "dk1",
      }),
      align: o.align ?? "left",
      valign: o.valign ?? "top",
      margin: toMargin(o.margin ?? 0),
      paraSpaceAfter: o.psa ?? 0,
    },
    name: o.name ?? null,
  };
  s.elements.push(element);
}

/**
 * 始点 (x1, y1) から終点 (x2, y2) への矢印を足す。
 * 線の位置と大きさは 2 点を囲む四角で持ち、終点が始点より左なら左右を、上なら上下を反転するフラグを立てる。
 */
export function arrow(
  s: SlideFigure,
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  o: ArrowOptions = {},
): void {
  s.elements.push({
    kind: "line",
    x: Math.min(x1, x2),
    y: Math.min(y1, y2),
    w: Math.abs(x2 - x1),
    h: Math.abs(y2 - y1),
    flipH: x2 < x1,
    flipV: y2 < y1,
    color: o.color ?? "dk2",
    width: o.width ?? 1.5,
    dashed: o.dash ?? false,
    endArrow: o.noHead !== true,
    startArrow: o.both === true,
  });
}

/** 番号の入った円を足す。(x, y) は円を囲む四角の左上の角、d は直径 (インチ)。 */
export function badge(
  s: SlideFigure,
  n: number | string,
  x: number,
  y: number,
  d: number,
  o: BadgeOptions = {},
): void {
  s.elements.push({
    kind: "shape",
    shape: "ellipse",
    x,
    y,
    w: d,
    h: d,
    fill: { color: o.fill ?? "accent1", transparency: 0 },
    outline: null,
    text: {
      paragraphs: toParagraphs(String(n), {
        fontSize: o.fontSize ?? 12,
        bold: true,
        color: "lt1",
      }),
      align: "center",
      valign: "middle",
      margin: toMargin(0),
      paraSpaceAfter: 0,
    },
    name: null,
  });
}

/**
 * 題名を、スライドの上の決まった位置の文字の箱として足す。位置と書式は、元にした build.js の題名のプレースホルダーと同じ。
 * PowerPoint の書き出しは、この箱の位置と書式で題名のプレースホルダーを作り、そこに題名を入れる。
 * はみ出しの見積もりは、この箱で題名を見積もる。題名は構成案から読むので、資料ごとのスクリプトには渡さない (型 Parts に含めない)。
 * 位置は、スライドの大きさ (型 Deck の説明) を前提にする。
 */
export function title(s: SlideFigure, t: string): void {
  text(s, t, 0.5, 0.58, 9.0, 0.62, {
    fontSize: 24,
    bold: true,
    color: "dk1",
    valign: "middle",
    name: "title",
  });
}

/**
 * 一言 (そのスライドで伝えたいことの 1 文) を、スライドの下の決まった位置の文字の箱として足す。
 * 一言は構成案から読むので、資料ごとのスクリプトには渡さない (型 Parts に含めない)。
 * 位置は、スライドの大きさ (型 Deck の説明) を前提にする。
 */
export function takeaway(s: SlideFigure, t: string): void {
  text(s, t, 0.5, 4.78, 8.5, 0.42, {
    fontSize: 14,
    bold: true,
    color: "dk1",
    valign: "middle",
    name: "takeaway",
  });
}

/** 図の部分をまとめる背景のカード (文字の無い、角の丸い四角) を足す。 */
export function card(
  s: SlideFigure,
  x: number,
  y: number,
  w: number,
  h: number,
  o: CardOptions = {},
): void {
  s.elements.push({
    kind: "shape",
    shape: "roundRect",
    radius: 0.1,
    x,
    y,
    w,
    h,
    fill: { color: o.fill ?? "lt2", transparency: o.tr ?? 0 },
    outline: null,
    text: null,
    name: o.name ?? null,
  });
}

/**
 * 箇条書きの文字を作る。戻り値を関数 text や box に渡す。項目ごとに段落を分ける。
 * 指定しなかった書式は項目に書かず、受け取る部品の関数の書式を使う (型 RunInput の説明のとおり)。
 */
export function bullets(items: string[], o: BulletsOptions = {}): RunInput[] {
  return items.map((t, i) => {
    const item: RunInput = { text: t, bullet: true, breakLine: i < items.length - 1 };
    if (o.fontSize !== undefined) item.fontSize = o.fontSize;
    if (o.color !== undefined) item.color = o.color;
    return item;
  });
}

/** 資料ごとのスクリプトに渡す、部品の関数の集まり (計画の KTD2)。 */
export interface Parts {
  slide: typeof slide;
  box: typeof box;
  text: typeof text;
  arrow: typeof arrow;
  badge: typeof badge;
  card: typeof card;
  bullets: typeof bullets;
}

/** 資料ごとのスクリプトに渡す、部品の関数の集まりの値。 */
export const parts: Parts = { slide, box, text, arrow, badge, card, bullets };

// 入口のサブコマンド pptx の処理。check と同じ検査に合格したときだけ PowerPoint のファイルを書き、
// pptx のスキルの scripts/apply_theme.js でテーマの色を書き込み、scripts/office/validate.py で形式を検査する (計画の R10〜R12・U5)。
// pptx のスキルは、Claude のデスクトップアプリが配るもの (スキルの一覧での名前は anthropic-skills:pptx)。
// ディレクトリは、スキル build が引数で渡す。~/.claude の下などを探さない (計画の KTD11)。
// 入口のサブコマンド pptx の引数・出力・終了コードの SSOT は、ファイル src/cli.ts の --help。

import { spawnSync } from "node:child_process";
import { existsSync, rmSync, statSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { type CheckOptions, type CheckReport, checkDeck, deckPaths, ExecutionError, installedCache } from "../check/deck.ts";
import { type CachePaths, SPAWN_MAX_BUFFER, venvState } from "../setup/setup.ts";
import { applyThemeInput, loadPptxGen, renderPptx } from "./write.ts";

/** pptx のスキルのディレクトリと、使う 2 つのスクリプトのパス */
export interface PptxSkill {
  readonly dir: string;
  /** scripts/apply_theme.js */
  readonly applyTheme: string;
  /** scripts/office/validate.py */
  readonly validate: string;
}

/** pptx のスキルのディレクトリを受け取り、使う 2 つのスクリプトがあることを確認する。無ければ ExecutionError を送出する */
export function pptxSkill(dir: string): PptxSkill {
  const abs = resolve(dir);
  const skill: PptxSkill = {
    dir: abs,
    applyTheme: join(abs, "scripts", "apply_theme.js"),
    validate: join(abs, "scripts", "office", "validate.py"),
  };
  const missing = [skill.applyTheme, skill.validate].filter((p) => !existsSync(p));
  if (missing.length > 0) {
    throw new ExecutionError(
      `pptx のスキルのディレクトリ ${abs} に、次のファイルが無い:\n${missing.map((p) => `  ${p}`).join("\n")}\n` +
        "Claude のデスクトップアプリが配る pptx のスキル (スキルの一覧での名前は anthropic-skills:pptx) のディレクトリを渡す。" +
        "マーケットプレイス anthropic-agent-skills のプラグイン document-skills が配る pptx のスキルには、scripts/apply_theme.js が無い",
    );
  }
  return skill;
}

/**
 * テーマの色を PowerPoint のファイルに書き込む処理。pptxPath のファイルを書き換え、利用者に示す出力を返す。
 * 失敗したら ExecutionError を送出する。テストで差し替えられるよう、関数として渡す
 */
export type ApplyTheme = (pptxPath: string, themePath: string) => string;

/**
 * pptx のスキルの scripts/apply_theme.js を、環境変数 NODE_PATH にキャッシュの node_modules を指定した子プロセスで実行する
 * (計画の KTD8)。apply_theme.js は pptxgenjs に同梱の jszip を、require で NODE_PATH から探す
 */
export function skillApplyTheme(skill: PptxSkill, cache: CachePaths, env: NodeJS.ProcessEnv): ApplyTheme {
  return (pptxPath, themePath) => {
    const r = spawnSync(process.execPath, [skill.applyTheme, pptxPath, themePath], {
      env: { ...env, NODE_PATH: cache.nodeModulesDir },
      encoding: "utf8",
      maxBuffer: SPAWN_MAX_BUFFER,
    });
    const output = `${r.stdout}${r.stderr}`.trimEnd();
    if (r.error !== undefined || r.status !== 0) {
      throw new ExecutionError(
        `pptx のスキルの ${skill.applyTheme} が失敗した (終了コード ${String(r.status)}${r.error === undefined ? "" : `、${r.error.message}`}):\n${output}`,
      );
    }
    return output;
  };
}

/** pptx のスキルの scripts/office/validate.py の結果。ok が false なら、形式の誤りがある */
export interface ValidateResult {
  readonly ok: boolean;
  readonly output: string;
}

/**
 * pptx のスキルの scripts/office/validate.py を、キャッシュの venv の Python で実行する。
 * 終了コード 0 は誤りなし、1 は形式の誤りあり。それ以外は ExecutionError にする
 */
export function skillValidate(skill: PptxSkill, cache: CachePaths, pptxPath: string, env: NodeJS.ProcessEnv): ValidateResult {
  const r = spawnSync(cache.venvPython, [skill.validate, pptxPath], { env, encoding: "utf8", maxBuffer: SPAWN_MAX_BUFFER });
  const output = `${r.stdout}${r.stderr}`.trimEnd();
  if (r.error === undefined && (r.status === 0 || r.status === 1)) return { ok: r.status === 0, output };
  throw new ExecutionError(
    `pptx のスキルの ${skill.validate} を、${cache.venvPython} で実行できなかった (終了コード ${String(r.status)}` +
      `${r.error === undefined ? "" : `、${r.error.message}`}):\n${output}`,
  );
}

/** サブコマンド pptx の引数 */
export interface PptxOptions extends CheckOptions {
  /** pptx のスキルのディレクトリ */
  readonly skillDir: string;
  /** テーマの色を書き込む処理。省略すると、pptx のスキルの scripts/apply_theme.js を実行する */
  readonly applyTheme?: ApplyTheme;
}

/** サブコマンド pptx の結果 */
export interface PptxReport {
  readonly check: CheckReport;
  /** 書いた PowerPoint のファイル。check に指摘があれば null */
  readonly pptx: string | null;
  /** テーマの色を書き込む処理の出力 */
  readonly applyThemeOutput: string;
  /** validate.py の結果。check に指摘があれば null */
  readonly validate: ValidateResult | null;
}

/**
 * 前に書いた build/deck.pptx を消す。終了コード 2 で終了しうる確認 (pptx のスキル・ライブラリ・資料のディレクトリ) より前に呼ぶ。
 * 確認の後に消すと、確認で終了した実行の後に、前の実行のファイルが残る。
 * 資料のディレクトリのパスがディレクトリでなければ (無い・通常のファイル)、消すものは無く、後の関数 deckPaths が実行の誤りにする。
 * 消せないとき (build/deck.pptx がディレクトリのときなど) は、パスと理由を示す ExecutionError を送出する
 */
function removePreviousPptx(deckDir: string): void {
  const dir = resolve(deckDir);
  if (!existsSync(dir) || !statSync(dir).isDirectory()) return;
  const pptxPath = join(dir, "build", "deck.pptx");
  try {
    rmSync(pptxPath, { force: true });
  } catch (e) {
    throw new ExecutionError(`前に書いた ${pptxPath} を消せない: ${e instanceof Error ? e.message : String(e)}`);
  }
}

/**
 * 資料のディレクトリを検査し、指摘が無ければ build/deck.pptx を書き、テーマの色を書き込み、形式を検査する。
 * 前に書いた build/deck.pptx は、最初に消す (ファイルがあることと、最後の実行が書いたことを一致させるため)。
 * テーマの色の書き込みが失敗したら、書いたファイルも消す。validate.py が形式の誤りを見つけたときは、調べられるようファイルを残す
 */
export async function buildPptx(deckDir: string, options: PptxOptions): Promise<PptxReport> {
  removePreviousPptx(deckDir);
  const env = options.env ?? process.env;
  const skill = pptxSkill(options.skillDir);
  const cache = installedCache(options);
  if (venvState(cache) !== "installed") {
    throw new ExecutionError(
      `ライブラリ (Python の venv) が、キャッシュのディレクトリ ${cache.venvDir} に入っていない。` +
        "サブコマンド setup status で状態を確認し、setup install で入れる",
    );
  }
  const paths = deckPaths(deckDir);
  const pptxPath = join(paths.buildDir, "deck.pptx");
  const themePath = join(paths.buildDir, "theme.json");

  const check = await checkDeck(deckDir, options);
  if (check.deck === null) return { check, pptx: null, applyThemeOutput: "", validate: null };

  writeFileSync(pptxPath, await renderPptx(check.deck, loadPptxGen(cache.nodeModulesDir)));
  writeFileSync(themePath, `${JSON.stringify(applyThemeInput(check.deck.theme), null, 2)}\n`);
  const applyTheme = options.applyTheme ?? skillApplyTheme(skill, cache, env);
  let applyThemeOutput: string;
  try {
    applyThemeOutput = applyTheme(pptxPath, themePath);
  } catch (e) {
    rmSync(pptxPath, { force: true });
    const message = e instanceof Error ? e.message : String(e);
    throw new ExecutionError(`${message}\nテーマの色を書き込めなかったので、PowerPoint のファイル ${pptxPath} は消した`);
  }
  const validate = skillValidate(skill, cache, pptxPath, env);
  return { check, pptx: pptxPath, applyThemeOutput, validate };
}
