// Google スライドの資料の読み込みの結果 build/presentation.json の型と検査 (計画の KTD10・U6)。
// スキル publish では、Claude が Google スライドのコネクタで、項目を指定して (field mask は定数 PRESENTATION_FIELDS) 資料を読み込み、
// 結果をそのまま build/presentation.json に書く。サブコマンド requests は、このファイルの検査を通った値だけを使う。
// 形は、U11 の確認 (Issue #251 のコメント) で得た読み込みの結果に合わせた。

/**
 * 読み込みで指定する項目 (Google スライドの API の field mask)。
 * U11 で確かめた項目に、マスターの配色 (pageProperties.colorScheme) を足した。配色は、テーマの色と比べ、違うマスターだけを変えるために読む。
 * サブコマンド requests の --help で示す
 */
export const PRESENTATION_FIELDS =
  "revisionId,masters(objectId,pageProperties.colorScheme)," +
  "slides(objectId,slideProperties(masterObjectId,notesPage(notesProperties.speakerNotesObjectId," +
  "pageElements(objectId,shape(shapeType,placeholder.type,text.textElements.textRun.content)))))";

/** 検査の誤りに添える、build/presentation.json に期待する形。サブコマンド requests の --help でも示す */
export const PRESENTATION_SHAPE = `{
  "revisionId": "<資料の版の ID>",
  "masters": [
    { "objectId": "<マスターの ID>",
      "pageProperties": { "colorScheme": { "colors": [ { "type": "DARK1", "color": { "red": 0〜1, "green": 0〜1, "blue": 0〜1 } }, … ] } } }
  ],
  "slides": [
    { "objectId": "<スライドの ID>",
      "slideProperties": { "notesPage": {
        "notesProperties": { "speakerNotesObjectId": "<ノートの欄の ID>" },
        "pageElements": [ { "objectId": "<ノートの欄の ID>", "shape": { "text": { "textElements": [ { "textRun": { "content": "…" } } ] } } }, … ]
      } } }
  ]
}
masters は 1 つ以上。slides は資料のスライドの順序で、空でもよい。ノートの欄が空なら、その要素に text が無い。
色の成分が 0 なら、その成分は無くてよい。`;

/** 色の 3 つの成分 (0〜1)。 */
export interface RgbColor {
  red: number;
  green: number;
  blue: number;
}

/** 読み込んだマスター。colors は、配色の種類 (DARK1・ACCENT1 など) ごとの色。 */
export interface PresentationMaster {
  objectId: string;
  colors: ReadonlyMap<string, RgbColor>;
}

/**
 * 読み込んだスライド。notesText はノートの欄の文 (textRun の content をつないだもの。Google スライドは末尾に改行を付ける)。
 * 欄が空 (要素に text が無い) なら null。空の欄の文を消す指示は失敗するので、空かどうかを区別する (計画の KTD10)
 */
export interface PresentationSlide {
  objectId: string;
  notesObjectId: string;
  notesText: string | null;
}

/** 検査を通った読み込みの結果。slides の順序は、資料のスライドの順序。 */
export interface Presentation {
  revisionId: string;
  masters: PresentationMaster[];
  slides: PresentationSlide[];
}

export type ParsePresentationResult = { ok: true; presentation: Presentation } | { ok: false; errors: string[] };

type Json = Record<string, unknown>;

function isObject(v: unknown): v is Json {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

/** 読み込みの結果の検査。誤りは、場所 (JSON の中のパス) を付けてすべて集める */
class Checker {
  readonly errors: string[] = [];

  fail(path: string, message: string): void {
    this.errors.push(`${path}: ${message}`);
  }

  object(v: unknown, path: string): Json | null {
    if (isObject(v)) return v;
    this.fail(path, v === undefined ? "無い" : "オブジェクトではない");
    return null;
  }

  array(v: unknown, path: string): unknown[] | null {
    if (Array.isArray(v)) return v;
    this.fail(path, v === undefined ? "無い" : "配列ではない");
    return null;
  }

  string(v: unknown, path: string): string | null {
    if (typeof v === "string" && v !== "") return v;
    this.fail(path, v === undefined ? "無い" : "空でない文字列ではない");
    return null;
  }
}

function parseColor(c: Checker, v: unknown, path: string): RgbColor | null {
  const o = c.object(v, path);
  if (o === null) return null;
  const color: RgbColor = { red: 0, green: 0, blue: 0 };
  let ok = true;
  for (const name of ["red", "green", "blue"] as const) {
    const value = o[name];
    // 成分が 0 のときは、読み込みの結果からその成分が除かれる (U11 の確認)
    if (value === undefined) continue;
    if (typeof value !== "number" || value < 0 || value > 1) {
      c.fail(`${path}.${name}`, "0〜1 の数ではない");
      ok = false;
      continue;
    }
    color[name] = value;
  }
  return ok ? color : null;
}

function parseMaster(c: Checker, v: unknown, path: string): PresentationMaster | null {
  const o = c.object(v, path);
  if (o === null) return null;
  const objectId = c.string(o["objectId"], `${path}.objectId`);
  const pageProperties = c.object(o["pageProperties"], `${path}.pageProperties`);
  const scheme = pageProperties === null ? null : c.object(pageProperties["colorScheme"], `${path}.pageProperties.colorScheme`);
  const list = scheme === null ? null : c.array(scheme["colors"], `${path}.pageProperties.colorScheme.colors`);
  if (objectId === null || list === null) return null;
  const colors = new Map<string, RgbColor>();
  list.forEach((item, i) => {
    const p = `${path}.pageProperties.colorScheme.colors[${String(i)}]`;
    const entry = c.object(item, p);
    if (entry === null) return;
    const type = c.string(entry["type"], `${p}.type`);
    const color = parseColor(c, entry["color"], `${p}.color`);
    if (type !== null && color !== null) colors.set(type, color);
  });
  return { objectId, colors };
}

/** ノートの欄の要素の text から、文をつないで返す。text が無ければ null */
function notesText(c: Checker, element: Json, path: string): string | null {
  const shape = c.object(element["shape"], `${path}.shape`);
  if (shape === null) return null;
  const text = shape["text"];
  if (text === undefined) return null;
  const body = c.object(text, `${path}.shape.text`);
  const elements = body === null ? null : c.array(body["textElements"], `${path}.shape.text.textElements`);
  if (elements === null) return null;
  // 段落の始まりを表す要素は、項目の指定で中身が除かれて {} になる (U11 の確認)。textRun を持つ要素だけをつなぐ
  return elements
    .map((e) => (isObject(e) && isObject(e["textRun"]) && typeof e["textRun"]["content"] === "string" ? e["textRun"]["content"] : ""))
    .join("");
}

function parseSlide(c: Checker, v: unknown, path: string): PresentationSlide | null {
  const o = c.object(v, path);
  if (o === null) return null;
  const objectId = c.string(o["objectId"], `${path}.objectId`);
  const props = c.object(o["slideProperties"], `${path}.slideProperties`);
  const notesPage = props === null ? null : c.object(props["notesPage"], `${path}.slideProperties.notesPage`);
  if (notesPage === null) return null;
  const notesPath = `${path}.slideProperties.notesPage`;
  const notesProperties = c.object(notesPage["notesProperties"], `${notesPath}.notesProperties`);
  const notesObjectId =
    notesProperties === null
      ? null
      : c.string(notesProperties["speakerNotesObjectId"], `${notesPath}.notesProperties.speakerNotesObjectId`);
  const elements = c.array(notesPage["pageElements"], `${notesPath}.pageElements`);
  if (objectId === null || notesObjectId === null || elements === null) return null;
  const index = elements.findIndex((e) => isObject(e) && e["objectId"] === notesObjectId);
  const element = elements[index];
  if (!isObject(element)) {
    c.fail(`${notesPath}.pageElements`, `ノートの欄の ID ${notesObjectId} を持つ要素が無い`);
    return null;
  }
  const text = notesText(c, element, `${notesPath}.pageElements[${String(index)}]`);
  return { objectId, notesObjectId, notesText: text };
}

/**
 * build/presentation.json の内容 (JSON.parse の結果) を検査する。
 * 形が違えば、場所を付けた誤りをすべて返す (表示するときは PRESENTATION_SHAPE を添える)
 */
export function parsePresentation(json: unknown): ParsePresentationResult {
  const c = new Checker();
  const root = c.object(json, "(全体)");
  if (root === null) return { ok: false, errors: c.errors };
  const revisionId = c.string(root["revisionId"], "revisionId");
  const masterList = c.array(root["masters"], "masters");
  if (masterList?.length === 0) c.fail("masters", "空 (マスターが 1 つ以上要る)");
  const slideList = c.array(root["slides"], "slides");
  const masters = (masterList ?? []).map((m, i) => parseMaster(c, m, `masters[${String(i)}]`));
  const slides = (slideList ?? []).map((s, i) => parseSlide(c, s, `slides[${String(i)}]`));
  const ids = new Set<string>();
  for (const [i, s] of slides.entries()) {
    if (s === null) continue;
    if (ids.has(s.objectId)) c.fail(`slides[${String(i)}].objectId`, `スライドの ID ${s.objectId} が 2 回ある`);
    ids.add(s.objectId);
  }
  if (c.errors.length > 0 || revisionId === null) return { ok: false, errors: c.errors };
  return {
    ok: true,
    presentation: {
      revisionId,
      masters: masters.filter((m) => m !== null),
      slides: slides.filter((s) => s !== null),
    },
  };
}

// 構成案のスライドと、Google スライドの資料の読み込みの結果を比べ、キーごとの作業 (作る・作り直す・消す・そのまま) と、
// 資料のスライドに対する操作の順序を求める (計画の R17・R19・KTD9・KTD10・U6)。
// 作業は、資料を読むだけで機械的に決まる。途中で失敗しても、読み直してもう一度求めれば、残りの作業だけになる (計画の R19)。

import { createHash } from "node:crypto";
import type { Theme } from "../data/theme.ts";
import type { Slide } from "../data/types.ts";
import type { Presentation } from "./presentation.ts";

/** スライドの ID の接頭辞。キーの無いスライド (利用者が足したもの) と区別するため、と ID の長さの下限 (5 文字) を満たすため */
export const SLIDE_ID_PREFIX = "sd_";

/** ハッシュ値の 16 進数の桁数 (計画の KTD9) */
const HASH_LENGTH = 10;

// キーは構成案の書式で [a-z0-9-] の 1〜32 文字に限る (ファイル src/outline/parse.ts)。区切りの _ はキーに入らない
const SLIDE_ID_PATTERN = new RegExp(`^${SLIDE_ID_PREFIX}([a-z0-9-]{1,32})_([0-9a-f]{${String(HASH_LENGTH)}})$`);

/** キーと値の順序を決めて JSON にする。プロパティの順序でハッシュ値が変わらないようにするため */
function stableJson(v: unknown): string {
  if (Array.isArray(v)) return `[${v.map(stableJson).join(",")}]`;
  if (typeof v === "object" && v !== null) {
    const entries = Object.entries(v)
      .filter(([, value]) => value !== undefined)
      .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
    return `{${entries.map(([k, value]) => `${JSON.stringify(k)}:${stableJson(value)}`).join(",")}}`;
  }
  return JSON.stringify(v);
}

/**
 * スライドの内容のハッシュ値 (SHA-256 の先頭 10 文字)。
 * 入力は、題名・一言・図の要素と、指示に書くテーマのフォント (見出しと本文) で、キー・位置・発表者ノートを含めない (計画の KTD9)。
 * ノートだけの修正や、前へのスライドの挿入で、変えていないスライドまで作り直しにならないため。
 * フォントを含めるのは、テーマのフォントだけを変えたときにも、スライドを作り直すため (U6 を実装するときに決めた)
 */
export function slideHash(slide: Pick<Slide, "title" | "takeaway" | "elements">, fonts: Theme["fonts"]): string {
  const input = stableJson({ title: slide.title, takeaway: slide.takeaway, elements: slide.elements, fonts });
  return createHash("sha256").update(input).digest("hex").slice(0, HASH_LENGTH);
}

/** スライドの ID (sd_<キー>_<ハッシュ値>) */
export function slideObjectId(key: string, hash: string): string {
  return `${SLIDE_ID_PREFIX}${key}_${hash}`;
}

/** スライドの ID からキーとハッシュ値を取り出す。キーの形でない ID (キーの無いスライド) は null */
export function parseSlideObjectId(id: string): { key: string; hash: string } | null {
  const m = SLIDE_ID_PATTERN.exec(id);
  if (m === null) return null;
  const [, key = "", hash = ""] = m;
  return { key, hash };
}

/** 読み込みの結果がスライドの作業を決められないとき (同じキーのスライドが 2 枚あるなど) の誤り */
export class PlanError extends Error {
  override name = "PlanError";
}

/**
 * 構成案のキーごとの作業。
 * create は作る、recreate は作り直す (内容が変わったか、--recreate-all を指定した)、keep はそのまま。
 */
export type KeyAction = "create" | "recreate" | "keep";

/** 構成案の 1 枚のスライドの作業。oldId は資料にあるスライドの ID (作るときは null)、newId は作業の後の ID */
export interface KeyPlan {
  key: string;
  action: KeyAction;
  oldId: string | null;
  newId: string;
}

/**
 * 資料のスライドに対する操作。指示の作成 (ファイル src/gslides/requests.ts) は、この順序で指示に変える。
 * - delete: スライドを消す。
 * - move: 並んだスライドを、まとめて insertionIndex の位置に動かす (Google スライドの API の updateSlidesPosition)。
 *   insertionIndex は、動かす前の並びでの位置。
 * - create: スライドを insertionIndex の位置に作る。replaceId があれば、作り直し。replaceFirst が false なら作った後に、
 *   true なら作る前に、replaceId のスライドを消す (新しい ID が古い ID と同じときは、先に消さないと ID が重なるため)。
 */
export type SlideStep =
  | { kind: "delete"; objectId: string }
  | { kind: "move"; objectIds: string[]; insertionIndex: number }
  | { kind: "create"; slide: Slide; objectId: string; insertionIndex: number; replaceId: string | null; replaceFirst: boolean };

/** 構成案と資料の差 */
export interface SlidePlan {
  /** 構成案の順序の、キーごとの作業 */
  keys: KeyPlan[];
  /** 構成案から消したキーの、資料のスライド (消す) */
  removed: { key: string; objectId: string }[];
  /** キーの無いスライドの ID (触れない) */
  untouched: string[];
  /** 新しく作った資料の、最初からあるスライドの ID (消す)。新しい資料でなければ null */
  initialSlideId: string | null;
  /** 操作の順序。delete と move を先に、create を構成案の順序で並べる */
  steps: SlideStep[];
}

/** 計算するときの資料のスライドの並び。キーのあるスライドは key を持つ */
interface Current {
  id: string;
  key: string | null;
}

/**
 * スライドの並びを、先頭のキーの無いスライドの集まりと、キーのあるスライドごとの集まり (そのスライドと、直後に続くキーの無いスライド) に分ける。
 * キーの無いスライドは、直前のキーのあるスライドと一緒に動く (計画の R17)
 */
function groups(list: readonly Current[]): { head: string[]; byKey: Map<string, string[]> } {
  const head: string[] = [];
  const byKey = new Map<string, string[]>();
  let current = head;
  for (const s of list) {
    if (s.key !== null) {
      current = [s.id];
      byKey.set(s.key, current);
    } else {
      current.push(s.id);
    }
  }
  return { head, byKey };
}

/**
 * 構成案のスライドと読み込みの結果から、作業を求める。
 * fonts はハッシュ値に含めるテーマのフォント。recreateAll が true なら、ハッシュ値が一致するスライドも作り直す
 * (プラグインの版が変わり、利用者がすべて作り直すことを選んだとき。計画の KTD10)
 */
export function planSlides(
  slides: readonly Slide[],
  fonts: Theme["fonts"],
  presentation: Presentation,
  recreateAll: boolean,
): SlidePlan {
  // 新しく作った資料は、キーの形でない ID のスライドが 1 枚だけある。そのスライドは最初からあるタイトルのスライドなので消す (計画の R15)。
  // 最初のファイルが失敗しても、読み直したときに同じ条件になるので、やり直しで消せる (U6 を実装するときに決めた)
  const [only] = presentation.slides;
  const initialSlideId =
    presentation.slides.length === 1 && only !== undefined && parseSlideObjectId(only.objectId) === null ? only.objectId : null;

  let current: Current[] = presentation.slides
    .filter((s) => s.objectId !== initialSlideId)
    .map((s) => ({ id: s.objectId, key: parseSlideObjectId(s.objectId)?.key ?? null }));
  const existing = new Map<string, string>();
  for (const s of current) {
    if (s.key === null) continue;
    const before = existing.get(s.key);
    if (before !== undefined) {
      throw new PlanError(`資料に、キー ${s.key} のスライドが 2 枚ある (${before} と ${s.id})。どちらかを Google スライドで消してから、読み直す`);
    }
    existing.set(s.key, s.id);
  }

  const outlineKeys = new Set(slides.map((s) => s.key));
  const keys: KeyPlan[] = slides.map((s) => {
    const newId = slideObjectId(s.key, slideHash(s, fonts));
    const oldId = existing.get(s.key) ?? null;
    if (oldId === null) return { key: s.key, action: "create", oldId, newId };
    if (oldId === newId && !recreateAll) return { key: s.key, action: "keep", oldId, newId };
    return { key: s.key, action: "recreate", oldId, newId };
  });
  const removed = current.filter((s) => s.key !== null && !outlineKeys.has(s.key)).map((s) => ({ key: s.key ?? "", objectId: s.id }));
  const untouched = current.filter((s) => s.key === null).map((s) => s.id);

  const steps: SlideStep[] = [];
  if (initialSlideId !== null) steps.push({ kind: "delete", objectId: initialSlideId });
  for (const r of removed) steps.push({ kind: "delete", objectId: r.objectId });
  const removedIds = new Set(removed.map((r) => r.objectId));
  current = current.filter((s) => !removedIds.has(s.id));

  // 資料にあるキーのスライドを、構成案の順序に並べ替える。先頭から順に、あるべき位置に無い集まりを、その位置へ動かす。
  // 前の位置は決まっているので、動かす集まりは常にあるべき位置より後ろにあり、動かす前の並びでの位置がそのまま insertionIndex になる
  const { head, byKey } = groups(current);
  let order = current.map((s) => s.id);
  let position = head.length;
  for (const k of keys) {
    const group = byKey.get(k.key);
    if (group === undefined) continue;
    const [first = ""] = group;
    const at = order.indexOf(first);
    if (at !== position) {
      steps.push({ kind: "move", objectIds: group, insertionIndex: position });
      order = order.filter((id) => !group.includes(id));
      order.splice(position, 0, ...group);
    }
    position += group.length;
  }

  // 作る・作り直すスライドを、構成案の順序で処理する。作るスライドは、構成案で 1 つ前のキーの集まりの後ろ
  // (キーの無いスライドが続いていれば、その後ろ) に入れる。前のキーは、この時点で資料にある
  const groupOf = (key: string, id: string): string[] => byKey.get(key) ?? [id];
  let previous: string[] = head;
  for (const [i, k] of keys.entries()) {
    const slide = slides[i];
    if (slide === undefined) continue;
    if (k.action === "create") {
      const last = previous.at(-1);
      const insertionIndex = last === undefined ? 0 : order.indexOf(last) + 1;
      steps.push({ kind: "create", slide, objectId: k.newId, insertionIndex, replaceId: null, replaceFirst: false });
      order.splice(insertionIndex, 0, k.newId);
      byKey.set(k.key, [k.newId]);
    } else if (k.action === "recreate" && k.oldId !== null) {
      // 作り直しは、新しい ID で同じ位置に作り、古いスライドを消す (計画の U6 の Approach 4)
      const insertionIndex = order.indexOf(k.oldId);
      const replaceFirst = k.oldId === k.newId;
      steps.push({ kind: "create", slide, objectId: k.newId, insertionIndex, replaceId: k.oldId, replaceFirst });
      order[insertionIndex] = k.newId;
      byKey.set(k.key, groupOf(k.key, k.oldId).map((id) => (id === k.oldId ? k.newId : id)));
    }
    previous = groupOf(k.key, k.newId);
  }
  return { keys, removed, untouched, initialSlideId, steps };
}

// スライドのデータから、Google スライドの API のメソッド presentations.batchUpdate に渡す指示 (requests) を作る (計画の R11・R17・KTD9・KTD14・U6)。
// 要素ごとの変換は、元にしたツール gslides.js の関数 slideRequests・lineRequests・textRequests・colorSchemeRequest を引き継いだ。
// Google スライドの API の挙動への対処 (計画の KTD14) は、対処ごとに理由をコメントに書いた。
// 指示に資料の版の ID (revisionId) は書かない。Claude が送る直前に読んだ値を付ける (計画の R16)。

import { title as titleBox, takeaway as takeawayBox, slide as emptyFigure } from "../data/parts.ts";
import { type SchemeColorName, schemeColorValues, type Theme } from "../data/theme.ts";
import type {
  LineElement,
  Paragraph,
  Rect,
  ShapeElement,
  ShapeKind,
  Slide,
  SlideFigure,
  TextBody,
  TextBoxElement,
  ThemeColorName,
} from "../data/types.ts";
import type { SlidePlan, SlideStep } from "./plan.ts";
import type { Presentation, PresentationMaster } from "./presentation.ts";

/** batchUpdate の 1 つの指示。形は Google スライドの API の Request */
export type Request = Record<string, unknown>;

const EMU_PER_INCH = 914_400;

// 基準の大きさ (EMU)。Google スライドは、図形の大きさを基準の大きさと拡大率で表し、読み込むと大きさは常にこの値になる
// (Issue #242 の表)。後から大きさを変えるときに、読み込んだ拡大率をそのまま計算に使えるよう、作るときから同じ形で表す
const BASE_SIZE_EMU = 3_000_000;

// Google スライドの文字の内側の余白 (インチ)。API では変えられないので、文字の箱をこの分だけ広げて、文字を置く範囲をデータに合わせる。
// はみ出しの見積もり (ファイル src/fit/estimate.ts の GOOGLE_MARGIN) と同じ値
const PADDING = { x: 0.1, y: 0.05 } as const;

// 箇条書きの字下げ (ポイント)。はみ出しの見積もりと PowerPoint の書き出しと同じ値
const BULLET_INDENT_PT = 16;

// 角の丸い四角を、この大きさ (インチ) を超えたら四角で描く
const ROUND_RECT_MAX = 1.0;

/** 1 枚のスライドの図形の番号の上限。ID の長さを 50 文字以下にするため、番号は 3 桁まで (計画の KTD9) */
export const MAX_OBJECTS_PER_SLIDE = 1000;

/** テーマの色の名前を、Google スライドの配色の種類にする */
const THEME_COLOR: Record<ThemeColorName, string> = {
  dk1: "DARK1",
  lt1: "LIGHT1",
  dk2: "DARK2",
  lt2: "LIGHT2",
  accent1: "ACCENT1",
  accent2: "ACCENT2",
  accent3: "ACCENT3",
  accent4: "ACCENT4",
  accent5: "ACCENT5",
  accent6: "ACCENT6",
};

/** テーマの 12 色の名前を、Google スライドの配色の種類にする */
const SCHEME_TYPE: Record<SchemeColorName, string> = {
  ...THEME_COLOR,
  hlink: "HYPERLINK",
  folHlink: "FOLLOWED_HYPERLINK",
};

const SHAPE_TYPE: Record<ShapeKind, string> = {
  roundRect: "ROUND_RECTANGLE",
  rect: "RECTANGLE",
  ellipse: "ELLIPSE",
  can: "CAN",
  chevron: "CHEVRON",
  homePlate: "HOME_PLATE",
};

// 中の文字を、図形に重ねた文字の箱に分ける形
const OVERLAY_SHAPES: ReadonlySet<ShapeKind> = new Set(["ellipse", "can", "chevron", "homePlate"]);

const ALIGN = { left: "START", center: "CENTER", right: "END" } as const;
const VALIGN = { top: "TOP", middle: "MIDDLE", bottom: "BOTTOM" } as const;

/** 16 進数 6 桁の色を、0〜255 の 3 つの成分にする */
function rgb255(hex: string): [number, number, number] {
  const n = parseInt(hex, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function themeColor(name: ThemeColorName): Record<string, string> {
  return { themeColor: THEME_COLOR[name] };
}

const round = (v: number, digits: number): number => Number(v.toFixed(digits));

/** 1 つの軸の大きさ (インチ) を、大きさ (EMU) と拡大率にする */
function axis(length: number): { size: number; scale: number } {
  // 大きさが 0 の軸 (縦や横の線) は、拡大率 0 にせず、元の gslides.js と同じく大きさ 0・拡大率 1 にする。
  // 拡大率 0 を Google スライドが受け付けるかは確かめていない (U6 を実装するときに決めた)
  if (length === 0) return { size: 0, scale: 1 };
  return { size: BASE_SIZE_EMU, scale: round((length * EMU_PER_INCH) / BASE_SIZE_EMU, 7) };
}

/** 要素の位置と大きさ。flipH・flipV なら、その軸の拡大率を負にし、始点を反対の端にする */
function elementProperties(page: string, r: Rect, flipH = false, flipV = false): Request {
  const x = axis(r.w);
  const y = axis(r.h);
  return {
    pageObjectId: page,
    size: { width: { magnitude: x.size, unit: "EMU" }, height: { magnitude: y.size, unit: "EMU" } },
    transform: {
      scaleX: flipH ? -x.scale : x.scale,
      scaleY: flipV ? -y.scale : y.scale,
      translateX: Math.round((flipH ? r.x + r.w : r.x) * EMU_PER_INCH),
      translateY: Math.round((flipV ? r.y + r.h : r.y) * EMU_PER_INCH),
      unit: "EMU",
    },
  };
}

/**
 * 文字の箱の位置と大きさ。データの内側の余白の分だけ狭めてから、Google スライドの余白の分だけ広げる。
 * Google スライドの余白は API で変えられないので、こうすると文字を置く範囲が、データの箱から余白を引いた範囲と一致する
 * (余白 0 の箱は、Google スライドの余白の分だけ広がる。余白が 0 でない箱の扱いは、U6 を実装するときに決めた)
 */
function textBoxRect(r: Rect, body: TextBody): Rect {
  const m = body.margin;
  return {
    x: r.x + m.left / 72 - PADDING.x,
    y: r.y + m.top / 72 - PADDING.y,
    w: r.w - (m.left + m.right) / 72 + 2 * PADDING.x,
    h: r.h - (m.top + m.bottom) / 72 + 2 * PADDING.y,
  };
}

/** 文字の書式で使うフォント。題名は見出しのフォント、ほかは本文のフォント */
interface Fonts {
  family: string;
}

/** 段落の文字。段落を改行でつなぐ */
function joinParagraphs(paragraphs: readonly Paragraph[]): string {
  return paragraphs.map((p) => p.runs.map((r) => r.text).join("")).join("\n");
}

/** 文字の範囲 (文字の位置。Google スライドの API の位置は UTF-16 の単位で数える) */
interface Span {
  start: number;
  end: number;
}

/** 箇条書きの段落が続く範囲 */
function bulletSpans(paragraphs: readonly Paragraph[]): Span[] {
  const spans: Span[] = [];
  let at = 0;
  let open: Span | null = null;
  paragraphs.forEach((p, i) => {
    const length = p.runs.reduce((n, r) => n + r.text.length, 0) + (i < paragraphs.length - 1 ? 1 : 0);
    if (p.bullet) {
      if (open === null) {
        open = { start: at, end: at + length };
        spans.push(open);
      } else open.end = at + length;
    } else open = null;
    at += length;
  });
  return spans.filter((s) => s.end > s.start);
}

/** 文字の指示。文字が空なら、指示は無い */
function textRequests(objectId: string, body: TextBody, isTextBox: boolean, fonts: Fonts): Request[] {
  const full = joinParagraphs(body.paragraphs);
  if (full === "") return [];
  const reqs: Request[] = [{ insertText: { objectId, text: full } }];

  const runs: { span: Span; style: Record<string, unknown>; fields: string }[] = [];
  let at = 0;
  body.paragraphs.forEach((p, pi) => {
    p.runs.forEach((r, ri) => {
      const start = at;
      at += r.text.length;
      // 段落の区切りの改行を、その段落の最後の部分の範囲に含める。
      // 含めないと、改行の文字だけが書式の付かない (デフォルトの大きさの) まま残り、その行が高くなる (計画の KTD14)
      if (ri === p.runs.length - 1 && pi < body.paragraphs.length - 1) at += 1;
      const style: Record<string, unknown> = {
        fontFamily: fonts.family,
        fontSize: { magnitude: r.fontSize, unit: "PT" },
      };
      // 新しい箱の文字は太字ではないので、太字のときだけ指定する (指示を短くするため。元の gslides.js と同じ)
      if (r.bold) style["bold"] = true;
      style["foregroundColor"] = { opaqueColor: themeColor(r.color) };
      if (r.link !== null) style["link"] = { url: r.link };
      const fields = `fontFamily,fontSize${r.bold ? ",bold" : ""},foregroundColor${r.link !== null ? ",link" : ""}`;
      runs.push({ span: { start, end: at }, style, fields });
    });
  });
  const [first] = runs;
  const same = first !== undefined && runs.every((r) => JSON.stringify(r.style) === JSON.stringify(first.style));
  if (same) {
    reqs.push({ updateTextStyle: { objectId, textRange: { type: "ALL" }, style: first.style, fields: first.fields } });
  } else {
    for (const r of runs) {
      if (r.span.end === r.span.start) continue;
      reqs.push({
        updateTextStyle: {
          objectId,
          textRange: { type: "FIXED_RANGE", startIndex: r.span.start, endIndex: r.span.end },
          style: r.style,
          fields: r.fields,
        },
      });
    }
  }

  const paragraphStyle: Record<string, unknown> = {};
  const paragraphFields: string[] = [];
  // 文字の箱の横の揃え方のデフォルト値は左揃え (START) なので、そのときは指定しない (指示を短くするため)
  if (!isTextBox || body.align !== "left") {
    paragraphStyle["alignment"] = ALIGN[body.align];
    paragraphFields.push("alignment");
  }
  if (body.paraSpaceAfter > 0) {
    paragraphStyle["spaceBelow"] = { magnitude: body.paraSpaceAfter, unit: "PT" };
    paragraphFields.push("spaceBelow");
  }
  if (paragraphFields.length > 0) {
    reqs.push({
      updateParagraphStyle: { objectId, textRange: { type: "ALL" }, style: paragraphStyle, fields: paragraphFields.join(",") },
    });
  }

  const bullets = bulletSpans(body.paragraphs);
  const allBullets = body.paragraphs.every((p) => p.bullet);
  const ranges: Record<string, unknown>[] = allBullets
    ? [{ type: "ALL" }]
    : bullets.map((s) => ({ type: "FIXED_RANGE", startIndex: s.start, endIndex: s.end }));
  for (const textRange of ranges) {
    reqs.push({ createParagraphBullets: { objectId, textRange, bulletPreset: "BULLET_DISC_CIRCLE_SQUARE" } });
    // 箇条書きの字下げのデフォルト値は大きく、幅の狭い箱では行が折り返されるので、字下げを 16 ポイントにする (計画の KTD14)
    reqs.push({
      updateParagraphStyle: {
        objectId,
        textRange,
        style: { indentFirstLine: { magnitude: 0, unit: "PT" }, indentStart: { magnitude: BULLET_INDENT_PT, unit: "PT" } },
        fields: "indentFirstLine,indentStart",
      },
    });
  }
  return reqs;
}

/** 文字の箱の指示 */
function textBoxRequests(objectId: string, page: string, r: Rect, body: TextBody, fonts: Fonts): Request[] {
  const reqs: Request[] = [
    { createShape: { objectId, shapeType: "TEXT_BOX", elementProperties: elementProperties(page, textBoxRect(r, body)) } },
  ];
  // 文字の箱の縦の揃え方のデフォルト値は上揃え (TOP) なので、そのときは指定しない (指示を短くするため)
  if (body.valign !== "top") {
    reqs.push({
      updateShapeProperties: { objectId, shapeProperties: { contentAlignment: VALIGN[body.valign] }, fields: "contentAlignment" },
    });
  }
  reqs.push(...textRequests(objectId, body, true, fonts));
  return reqs;
}

/** 図形の指示。円・円柱・山形・五角形の矢印の中の文字は、図形に重ねた文字の箱にする */
function shapeRequests(nextId: () => string, page: string, e: ShapeElement, fonts: Fonts): Request[] {
  const objectId = nextId();
  let shapeType = SHAPE_TYPE[e.shape];
  // 角の丸い四角の丸みの大きさは API で変えられず、大きな箱では丸みが大きくなりすぎるので、大きな箱は四角で描く (計画の KTD14)
  if (e.shape === "roundRect" && Math.min(e.w, e.h) > ROUND_RECT_MAX) shapeType = "RECTANGLE";
  const reqs: Request[] = [{ createShape: { objectId, shapeType, elementProperties: elementProperties(page, e) } }];

  const solidFill: Record<string, unknown> = { color: themeColor(e.fill.color) };
  if (e.fill.transparency > 0) solidFill["alpha"] = round(1 - e.fill.transparency / 100, 3);
  const shapeProperties: Record<string, unknown> = { shapeBackgroundFill: { solidFill } };
  if (e.outline === null) {
    shapeProperties["outline"] = { propertyState: "NOT_RENDERED" };
  } else {
    const outline: Record<string, unknown> = {
      outlineFill: { solidFill: { color: themeColor(e.outline.color) } },
      weight: { magnitude: e.outline.width, unit: "PT" },
    };
    if (e.outline.dashed) outline["dashStyle"] = "DASH";
    shapeProperties["outline"] = outline;
  }
  const fields = ["shapeBackgroundFill", "outline"];
  const overlay = e.text !== null && OVERLAY_SHAPES.has(e.shape);
  if (e.text !== null && !overlay) {
    shapeProperties["contentAlignment"] = VALIGN[e.text.valign];
    fields.push("contentAlignment");
  }
  reqs.push({ updateShapeProperties: { objectId, shapeProperties, fields: fields.join(",") } });

  if (e.text === null) return reqs;
  if (overlay) {
    // Google スライドは、円・円柱・山形・五角形の矢印の中の文字を、図形の内側の狭い範囲に収めて折り返すので、
    // 図形と文字を分け、図形の外形に合わせた文字の箱を上に重ねる (計画の KTD14)
    reqs.push(...textBoxRequests(nextId(), page, e, e.text, fonts));
  } else {
    reqs.push(...textRequests(objectId, e.text, false, fonts));
  }
  return reqs;
}

/** 線の指示 */
function lineRequests(objectId: string, page: string, e: LineElement): Request[] {
  // 線の向きは、始点と終点ではなく拡大率の正負で表すので、右から左・下から上の線は、拡大率を負にする (計画の KTD14)
  const lineProperties: Record<string, unknown> = {
    lineFill: { solidFill: { color: themeColor(e.color) } },
    weight: { magnitude: e.width, unit: "PT" },
    dashStyle: e.dashed ? "DASH" : "SOLID",
    endArrow: e.endArrow ? "FILL_ARROW" : "NONE",
    startArrow: e.startArrow ? "FILL_ARROW" : "NONE",
  };
  return [
    // 線の種類は、非推奨の lineCategory ではなく category で指定する (計画の KTD14)
    { createLine: { objectId, category: "STRAIGHT", elementProperties: elementProperties(page, e, e.flipH, e.flipV) } },
    { updateLineProperties: { objectId, lineProperties, fields: "lineFill,weight,dashStyle,endArrow,startArrow" } },
  ];
}

/** 部品の関数 title か takeaway が作る文字の箱を取り出す */
function fixedBox(add: (s: SlideFigure, t: string) => void, key: string, t: string): TextBoxElement {
  const fig = emptyFigure(key);
  add(fig, t);
  const [box] = fig.elements;
  if (box?.kind !== "textBox") throw new Error(`題名か一言の部品の関数が、文字の箱を作らなかった (キー ${key})`);
  return box;
}

/**
 * 1 枚のスライドの、図形 (題名・図の要素・一言) と、その ID の数。図形の ID は <スライドの ID>_<番号> で、番号は 0 から数える。
 * 円などの中の文字は図形と文字の箱の 2 つになるので、要素の数より多くなることがある
 */
export function countObjects(slide: Slide): number {
  let n = 2;
  for (const e of slide.elements) n += e.kind === "shape" && e.text !== null && OVERLAY_SHAPES.has(e.shape) ? 2 : 1;
  return n;
}

/**
 * 1 枚のスライドを作る指示。スライドはレイアウト BLANK で作り、題名は部品の関数 title の箱の位置と書式で、普通の文字の箱として置く
 * (U6 を実装するときに決めた)。スライド番号は作らない。レイアウト BLANK のスライドに、スライド番号のプレースホルダーを作れないため
 * (計画の R22)
 */
export function slideRequests(slide: Slide, objectId: string, insertionIndex: number, fonts: Theme["fonts"]): Request[] {
  if (countObjects(slide) > MAX_OBJECTS_PER_SLIDE) {
    throw new Error(`スライド ${slide.key} の図形が ${String(MAX_OBJECTS_PER_SLIDE)} 個を超える`);
  }
  let n = 0;
  const nextId = (): string => `${objectId}_${String(n++)}`;
  const body: Fonts = { family: fonts.body };
  const reqs: Request[] = [
    { createSlide: { objectId, insertionIndex, slideLayoutReference: { predefinedLayout: "BLANK" } } },
  ];
  const title = fixedBox(titleBox, slide.key, slide.title);
  reqs.push(...textBoxRequests(nextId(), objectId, title, title.text, { family: fonts.heading }));
  for (const e of slide.elements) {
    switch (e.kind) {
      case "shape":
        reqs.push(...shapeRequests(nextId, objectId, e, body));
        break;
      case "textBox":
        reqs.push(...textBoxRequests(nextId(), objectId, e, e.text, body));
        break;
      case "line":
        reqs.push(...lineRequests(nextId(), objectId, e));
        break;
    }
  }
  const takeaway = fixedBox(takeawayBox, slide.key, slide.takeaway);
  reqs.push(...textBoxRequests(nextId(), objectId, takeaway, takeaway.text, body));
  return reqs;
}

/** マスターの配色が、テーマの 12 色と同じか。読み込んだ値は小数の最後の桁が違うことがあるので、0〜255 に丸めて比べる */
function sameScheme(master: PresentationMaster, theme: Theme): boolean {
  const values = schemeColorValues(theme);
  return Object.entries(SCHEME_TYPE).every(([name, type]) => {
    const read = master.colors.get(type);
    if (read === undefined) return false;
    const [r, g, b] = rgb255(values[name as SchemeColorName]);
    return Math.round(read.red * 255) === r && Math.round(read.green * 255) === g && Math.round(read.blue * 255) === b;
  });
}

/**
 * マスターの配色を、テーマの 12 色に変える指示。読み込んだ配色がテーマと違うマスターだけについて作る。
 * 図形の色はテーマの色で指定するので、配色を変えると、すべてのスライドの色が変わる (計画の R11)。
 * 配色は updatePageProperties の colorScheme で変えられる (計画の KTD14。U11 で確認した)
 */
export function colorSchemeRequests(presentation: Presentation, theme: Theme): Request[] {
  const values = schemeColorValues(theme);
  const colors = Object.entries(SCHEME_TYPE).map(([name, type]) => {
    const [red, green, blue] = rgb255(values[name as SchemeColorName]);
    return { type, color: { red: round(red / 255, 8), green: round(green / 255, 8), blue: round(blue / 255, 8) } };
  });
  return presentation.masters
    .filter((m) => !sameScheme(m, theme))
    .map((m) => ({
      updatePageProperties: { objectId: m.objectId, pageProperties: { colorScheme: { colors } }, fields: "colorScheme" },
    }));
}

/** 1 つの操作の指示 */
function stepRequests(step: SlideStep, fonts: Theme["fonts"]): Request[] {
  switch (step.kind) {
    case "delete":
      return [{ deleteObject: { objectId: step.objectId } }];
    case "move":
      return [{ updateSlidesPosition: { slideObjectIds: step.objectIds, insertionIndex: step.insertionIndex } }];
    case "create": {
      const create = slideRequests(step.slide, step.objectId, step.insertionIndex, fonts);
      if (step.replaceId === null) return create;
      const remove = { deleteObject: { objectId: step.replaceId } };
      return step.replaceFirst ? [remove, ...create] : [...create, remove];
    }
  }
}

/** 1 つのファイルに入れる、作る・作り直すスライドの数。1 枚分の指示は約 1 万字で、Bash の出力の上限の約 3 万字を超えないため (計画の KTD10) */
export const SLIDES_PER_FILE = 2;

/**
 * 作業を、指示のファイルごとの配列にする。最初のファイルの先頭に、配色・消す・並べ替える指示を入れ、
 * 作る・作り直すスライドを 2 枚ずつ入れる。作り直しの「作る」と「古いスライドを消す」は、同じファイルに入る。
 * 送る指示が無ければ、空の配列を返す
 */
export function slideRequestFiles(plan: SlidePlan, presentation: Presentation, theme: Theme): Request[][] {
  const head = [...colorSchemeRequests(presentation, theme)];
  const creates: SlideStep[] = [];
  for (const step of plan.steps) {
    if (step.kind === "create") creates.push(step);
    else head.push(...stepRequests(step, theme.fonts));
  }
  const files: Request[][] = [];
  for (let i = 0; i < creates.length; i += SLIDES_PER_FILE) {
    files.push(creates.slice(i, i + SLIDES_PER_FILE).flatMap((s) => stepRequests(s, theme.fonts)));
  }
  if (files.length === 0) return head.length === 0 ? [] : [head];
  const [first = []] = files;
  files[0] = [...head, ...first];
  return files;
}

// 発表者ノートの指示 (計画の R20・KTD10・U6)。
// ノートは、資料から読んだ文と構成案の文をキーごとに比べ、違うキーだけ入れ直す。スライドの ID のハッシュ値に含めないので、
// ノートだけを直してもスライドは作り直しにならない (計画の KTD9)。
// ノートの欄の ID はスライドを作った後でないと分からないので、作る・作り直すスライドのノートは、送った後に資料を読み直して作る。

import type { Slide } from "../data/types.ts";
import type { KeyPlan } from "./plan.ts";
import type { Presentation } from "./presentation.ts";
import type { Request } from "./requests.ts";

/** 1 つのファイルに入れる、ノートを入れ直すスライドの数。1 枚のノートが 1,000 字でも、Bash の出力の上限の約 3 万字に収まるため */
export const NOTES_PER_FILE = 10;

/** 読んだノートの欄の文を、構成案の文と比べられる形にする。Google スライドは文の末尾に改行を付けるので、それを除く */
function normalize(text: string | null): string {
  if (text === null) return "";
  return text.endsWith("\n") ? text.slice(0, -1) : text;
}

/** ノートを入れ直すスライド */
export interface NotesChange {
  key: string;
  requests: Request[];
}

/**
 * ノートを入れ直す指示を、キーごとに作る。対象は、作業が「そのまま」で、資料にいまの ID のスライドがあるキーだけ。
 * 作る・作り直すキーは、ノートの欄の ID がまだ分からないので、送った後に読み直して、もう一度求める。
 */
export function notesChanges(slides: readonly Slide[], keys: readonly KeyPlan[], presentation: Presentation): NotesChange[] {
  const byId = new Map(presentation.slides.map((s) => [s.objectId, s]));
  const changes: NotesChange[] = [];
  keys.forEach((k, i) => {
    const slide = slides[i];
    const read = byId.get(k.newId);
    if (k.action !== "keep" || slide === undefined || read === undefined) return;
    if (normalize(read.notesText) === slide.notes) return;
    const requests: Request[] = [];
    // 欄に文があれば、消してから入れる。空の欄の文を消す指示は失敗するので、空なら消さない (計画の KTD10)
    if (read.notesText !== null) {
      requests.push({ deleteText: { objectId: read.notesObjectId, textRange: { type: "ALL" } } });
    }
    if (slide.notes !== "") {
      requests.push({ insertText: { objectId: read.notesObjectId, insertionIndex: 0, text: slide.notes } });
    }
    changes.push({ key: k.key, requests });
  });
  return changes;
}

/** ノートの指示を、ファイルごとの配列にする (10 枚ずつ)。 */
export function notesRequestFiles(changes: readonly NotesChange[]): Request[][] {
  const files: Request[][] = [];
  for (let i = 0; i < changes.length; i += NOTES_PER_FILE) {
    files.push(changes.slice(i, i + NOTES_PER_FILE).flatMap((c) => c.requests));
  }
  return files;
}

